import{_ as n,o as t,c as o,af as e}from"./chunks/framework.B28LkSoM.js";const h=JSON.parse('{"title":"前端打包部署","description":"把开发机上跑得好好的前端工程变成一份能交给服务器的静态文件——一条打包命令产出 dist 目录，把里面的东西放进 Nginx 的 html 文件夹、启动 Nginx 从 80 端口访问；顺带说清 80 端口被占用时怎么查怎么办，以及 nginx 的三条命令","frontmatter":{"title":"前端打包部署","published":"2026-09-29T00:00:00.000Z","description":"把开发机上跑得好好的前端工程变成一份能交给服务器的静态文件——一条打包命令产出 dist 目录，把里面的东西放进 Nginx 的 html 文件夹、启动 Nginx 从 80 端口访问；顺带说清 80 端口被占用时怎么查怎么办，以及 nginx 的三条命令","tags":["JavaWeb","前端","部署"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-105-frontend-build-deploy.webp","order":105,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/105-前端打包部署.md","filePath":"posts/学习文档/JavaWeb学习笔记/105-前端打包部署.md"}'),a={name:"posts/学习文档/JavaWeb学习笔记/105-前端打包部署.md"};function d(i,s,c,p,l,r){return t(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...s[0]||(s[0]=[e(`<p><a href="/posts/编程学习/javaweb学习笔记/104-登录退出与令牌管理/">104 篇</a>把登录退出做完，Tlias 的前端功能就全了——但那时候它还只在<strong>自己电脑的开发服务器上</strong>跑着（<code>npm run dev</code> 起的 5173）。这一篇（第 18 章 PPT 第 21～30 页）是最后一步：<strong>把工程打包成静态文件，交给 Nginx，从 80 端口访问</strong>。</p><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p><strong>这一篇的打包与 nginx 部署本轮没有在本机实测</strong>——第 18 章这次实测只跑到登录退出（前端 dev 服务器 + 后端联调）。课上有两处旧实测可以参照：<a href="/posts/编程学习/javaweb学习笔记/95-前端工程化与vue项目/">95 篇</a>里跑过同版本脚手架的 <code>npm run build</code>（见过 <code>dist</code> 产物和它的大小），<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>里起过 Windows 版 nginx（那次监听的是 90 端口、配的是反向代理）。下面按 <strong>PPT 第 21～28 页的口径</strong>讲&quot;打包 → 部署 → 访问&quot;，凡引用上面两处旧实测的地方都会写明出处。</p></div><table tabindex="0"><thead><tr><th>PPT 页</th><th>内容</th><th>本篇对应小节</th></tr></thead><tbody><tr><td>21</td><td>目录页（员工管理-修改 / 员工管理-删除 / 登录退出 / 打包部署）</td><td>四张卡片只剩最后一张没点亮</td></tr><tr><td>22</td><td>小节标题页——打包部署 04</td><td>打包部署</td></tr><tr><td>23</td><td>前后端分离下的开发形态（前端开发 / 后端开发 / 接口文档，&quot;阅读-开发&quot;）</td><td>从开发到上线</td></tr><tr><td>24</td><td>打包（NPM 脚本面板 + 打包产物目录）</td><td>打包</td></tr><tr><td>25</td><td>Nginx 介绍（定义、官网）</td><td>Nginx 是什么</td></tr><tr><td>26</td><td>部署（复制 dist 里的文件到 html 目录；双击 nginx.exe；默认占用 80 端口）</td><td>部署三步</td></tr><tr><td>27</td><td>访问 <code>http://localhost:80</code> + 注意（80 被占用可改 nginx.conf；<code>netstat –ano | findStr 80</code>）</td><td>部署三步、80 端口被占用怎么办</td></tr><tr><td>28</td><td>前端项目的打包部署小结（打包 / 部署 / nginx 三条命令）</td><td>三条命令</td></tr><tr><td>29</td><td>班级管理 &amp; 学员管理（自己实现的两个页面）</td><td>班级管理 &amp; 学员管理</td></tr><tr><td>30</td><td>空白页——第 18 章收尾</td><td>本章到此结束</td></tr></tbody></table><h2 id="从开发到上线-ppt-第-21-23-页" tabindex="-1">从开发到上线（PPT 第 21～23 页） <a class="header-anchor" href="#从开发到上线-ppt-第-21-23-页" aria-label="Permalink to &quot;从开发到上线（PPT 第 21～23 页）&quot;">​</a></h2><p>第 21 页是那张目录页（&quot;员工管理-修改 / 员工管理-删除 / 登录退出 / 打包部署&quot;），<strong>前三张卡片都点亮了，只剩最后一张</strong>；第 22 页是小节标题页&quot;打包部署 04&quot;。</p><p>第 23 页回顾的是<strong>开发阶段</strong>的形态：前端工程师和后端工程师<strong>同时开工</strong>，前端拿着页面原型和需求写页面、后端照着接口文档写接口，两边约定好接口的路径、参数、响应格式，各自&quot;阅读—开发&quot;，中间靠<strong>请求/响应</strong>对接（这就是 <a href="/posts/编程学习/javaweb学习笔记/96-vue项目开发流程与组合式api/">96 篇</a>、<a href="/posts/编程学习/javaweb学习笔记/98-前后端分离与整体布局/">98 篇</a>一直在用的前后端分离模式）。这一页画的两样东西——一份前端工程（HTML/JS/CSS 那堆文件）、一份后端工程（Java 那堆文件）——正是现在电脑里躺着的两个项目。</p><p>开发阶段是怎么跑起来的，前面几篇已经交待过：前端 <code>npm run dev</code> 起 <strong>Vite 开发服务器</strong>（默认 5173），页面里的 <code>/api/...</code> 请求由 <code>vite.config.js</code> 里那段<strong>代理</strong>转发给后端（<a href="/posts/编程学习/javaweb学习笔记/99-部门管理-列表查询/">99 篇</a>配的，本机因为 8080 被占，后端换到了 8081 起、代理的 target 也跟着改）。</p><p><strong>上线</strong>要面对的是另一个问题：服务器上不会给你开一个 Vite 开发服务器。用户要的只是&quot;打开网址、看到页面&quot;，所以前端工程必须先变成<strong>浏览器能直接认的静态文件</strong>（一个 html + 一堆 css/js/图片），再交给一个 <strong>Web 服务器</strong>发出去——这就是这一篇剩下的三步：<strong>打包 → 部署 → 访问</strong>。</p><h2 id="打包-npm-run-build-→-dist-ppt-第-24-页" tabindex="-1">打包：<code>npm run build</code> → <code>dist</code>（PPT 第 24 页） <a class="header-anchor" href="#打包-npm-run-build-→-dist-ppt-第-24-页" aria-label="Permalink to &quot;打包：\`npm run build\` → \`dist\`（PPT 第 24 页）&quot;">​</a></h2><p>PPT 第 24 页只写了两个字：&quot;<strong>打包</strong>&quot;，配的两张图就是答案——一张是 <code>package.json</code> 的 NPM 脚本面板，另一张是打包之后的目录结构。</p><p>在工程根目录（有 <code>package.json</code> 的那一层）执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 把源码编译、压缩成可以直接部署的静态文件（输出到 dist 目录）</span></span></code></pre></div><p>命令名 <code>build</code> 是脚手架的约定，它真正执行什么写在 <code>package.json</code> 的 <code>scripts</code> 里。本课程这个工程（<code>vue-tlias-management</code>，JS 版模板）写的是：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;scripts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vite&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vite build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;preview&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vite preview --port 4173&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;lint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eslint . --ext .vue,.js,.jsx,.cjs,.mjs --fix --ignore-path .gitignore&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>也就是 <code>npm run build</code> = <strong><code>vite build</code></strong>：Vite 把 <code>src/</code> 下几百个 <code>.vue</code>、<code>.js</code> 模块编译、合并、压缩，输出到工程的 <strong><code>dist</code> 目录</strong>。</p><p><img src="https://img.tsh520.cn/file/blog/article/24-NPM%E8%84%9A%E6%9C%AC%E9%87%8C%E7%9A%84build.jpg" alt="NPM 脚本面板里的 build"><em>图：PPT 第 24 页的 NPM 脚本面板——<code>package.json</code> 里 <code>dev</code> / <code>build</code> / <code>preview</code> 等脚本一字排开，鼠标所在那行就是 <strong>build</strong>（&quot;跑的就是它&quot;）。这张图截的是课程模板工程（TypeScript 版，<code>build</code> 里还串了一步 <code>type-check</code>），所以脚本内容比本课程这份 <code>.js</code> 工程多几项——<strong>认的是&quot;build 这个脚本就是打包入口&quot;这件事，具体命令以自己工程的 <code>package.json</code> 为准</strong></em></p><p><img src="https://img.tsh520.cn/file/blog/article/24-%E6%89%93%E5%8C%85%E4%BA%A7%E7%89%A9dist%E7%9B%AE%E5%BD%95.jpg" alt="打包产物 dist 目录"><em>图：PPT 第 24、26 页配的打包产物——项目根目录下多出一个 <strong><code>dist</code></strong> 文件夹，里面是 <code>assets/</code>（编译后的 js、css 等）、<code>favicon.ico</code> 和 <code>index.html</code>。整个 <code>dist</code> 就是<strong>要交给服务器的那一份东西</strong>，源码、<code>node_modules</code>、配置文件都用不着带</em></p><p>打包到底干了什么，用大白话说三句：</p><ol><li><strong>编译</strong>：<code>.vue</code> 文件浏览器不认识，里面那套组合式 API、模板语法都要转成普通 JS；</li><li><strong>合并与压缩</strong>：上百个模块合成几个文件（<code>index.xxxx.js</code>、<code>index.xxxx.css</code>），多余的空格、注释、换行全去掉——体积能小一大截；</li><li><strong>产出静态文件</strong>：最终就是&quot;一个 <code>index.html</code> + 一个 <code>assets</code> 目录&quot;，<strong>不需要 Node、不需要 Vite</strong>，任何静态服务器都能发。</li></ol><p>打包结果长什么样，<a href="/posts/编程学习/javaweb学习笔记/95-前端工程化与vue项目/">95 篇</a>里对<strong>同版本脚手架建的工程</strong>实测过一次，可直接对照：</p><table tabindex="0"><thead><tr><th>产物</th><th>大小</th><th>gzip</th></tr></thead><tbody><tr><td><code>dist/index.html</code></td><td>0.42 KiB</td><td>—</td></tr><tr><td><code>dist/assets/index.xxxx.css</code></td><td>316.98 KiB</td><td>42.98 KiB</td></tr><tr><td><code>dist/assets/index.xxxx.js</code></td><td>877.21 KiB</td><td>290.77 KiB</td></tr></tbody></table><p>当时还带出一句提示 <code>chunks are larger than 500 KiB</code>——原因和 <a href="/posts/编程学习/javaweb学习笔记/97-elementplus组件库/">97 篇</a>说的一样：<strong>ElementPlus 是全量引入</strong>的，打包时会连没用到的组件样式一起带上（真实项目里会改成按需引入来瘦身）。本课程这个 Tlias 工程同样是全量引入，所以打包出来的体积也不会小——这是打包环节最容易先撞上的一件事，知道来龙去脉就够了。</p><h2 id="nginx-是什么-ppt-第-25-页" tabindex="-1">Nginx 是什么（PPT 第 25 页） <a class="header-anchor" href="#nginx-是什么-ppt-第-25-页" aria-label="Permalink to &quot;Nginx 是什么（PPT 第 25 页）&quot;">​</a></h2><p>有了 <code>dist</code> 这份静态文件，还得有个&quot;Web 服务器&quot;把它发出去——PPT 第 25 页介绍的就是它：</p><blockquote><p><strong>介绍</strong>：Nginx 是一款<strong>轻量级的 Web 服务器/反向代理服务器</strong>及电子邮件（IMAP/POP3）代理服务器。其特点是<strong>占有内存少，并发能力强</strong>，在各大型互联网公司都有非常广泛的使用。 <strong>官网</strong>：<a href="https://nginx.org/" target="_blank" rel="noreferrer">https://nginx.org/</a></p></blockquote><p><img src="https://img.tsh520.cn/file/blog/article/25-nginx%E5%AE%98%E7%BD%91%E4%B8%8B%E8%BD%BD%E9%A1%B5.jpg" alt="nginx 官网下载页"><em>图：PPT 第 25 页配的 nginx 官网下载页（nginx.org）——按版本分了三档：<strong>Mainline version</strong>（主线版，功能最新）、<strong>Stable version</strong>（稳定版）、<strong>Legacy versions</strong>（历史版本），每个版本都给 <code>nginx-1.x.x</code> 的源码包和 <code>nginx/Windows-1.x.x</code> 的 Windows 版包。生产环境一般选稳定版；课程里用的是 Windows 版（绿色免安装，解压即用）</em></p><p>这句话里有两个身份，我们<strong>都已经见过一次</strong>了：</p><table tabindex="0"><thead><tr><th>nginx 的身份</th><th>干什么</th><th>在哪见过</th></tr></thead><tbody><tr><td><strong>Web 服务器</strong>（静态）</td><td>把页面（html/css/js/图片）发给浏览器</td><td><strong>本篇</strong>——发前端打包产物</td></tr><tr><td><strong>反向代理服务器</strong></td><td>把请求转发给后端的服务器（可多个，安全、灵活、负载均衡）</td><td><a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>（第 7 章联调那次，nginx 监听 90 端口，把 <code>/api/depts</code> 转给 8080 的 Tomcat）</td></tr></tbody></table><p>同一个软件、两套用法。顺带回忆一件事：<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>里那个&quot;前端环境压缩包&quot;解出来的 nginx，<code>html</code> 目录里装的正是<strong>一份打包好的前端页面</strong>——那一份就是第 7 章的老师提前帮你 <code>npm run build</code> 出来的，本篇只是把这个动作自己做一遍。</p><h2 id="部署三步-ppt-第-26-27-页" tabindex="-1">部署三步（PPT 第 26～27 页） <a class="header-anchor" href="#部署三步-ppt-第-26-27-页" aria-label="Permalink to &quot;部署三步（PPT 第 26～27 页）&quot;">​</a></h2><p>第 26、27 页把部署说成三件事：</p><blockquote><p><strong>部署</strong>：将打包好的 dist 目录下的文件，复制到 nginx 安装目录的 <strong>html</strong> 目录下。 <strong>启动</strong>：双击 <strong>nginx.exe</strong> 文件即可，Nginx 服务器默认占用 <strong>80</strong> 端口号。 <strong>访问</strong>：<code>http://localhost:80</code></p></blockquote><table tabindex="0"><thead><tr><th>步</th><th>做什么</th><th>图上的说法</th></tr></thead><tbody><tr><td>① 部署（放文件）</td><td>把 <strong><code>dist</code> 目录里</strong>的东西（<code>index.html</code>、<code>assets/</code>、<code>favicon.ico</code>）复制到 nginx 安装目录的 <strong><code>html</code></strong> 目录下</td><td>&quot;将打包好的 dist 目录下的文件，复制到 nginx 安装目录的 html 目录下&quot;</td></tr><tr><td>② 启动（起服务）</td><td>到 nginx 安装目录里<strong>双击 <code>nginx.exe</code></strong>（或命令行执行它），nginx 默认监听 <strong>80</strong> 端口</td><td>&quot;双击 nginx.exe 文件即可，Nginx 服务器默认占用 80 端口号&quot;</td></tr><tr><td>③ 访问（用浏览器看）</td><td>浏览器打开 <strong><code>http://localhost:80</code></strong>（也就是 <code>http://localhost</code>）</td><td>&quot;访问：<a href="http://localhost:80" target="_blank" rel="noreferrer">http://localhost:80</a>&quot;</td></tr></tbody></table><p>注意第①步复制的是 <strong><code>dist</code> 里面</strong>的文件，不是把 <code>dist</code> 这个文件夹整个塞进 <code>html</code>：nginx 的静态服务是<strong>以 <code>html</code> 目录为根</strong>去找文件的，浏览器请求 <code>/</code> 时它去 <code>html</code> 下找 <code>index.html</code>；要是套了一层 <code>html/dist/index.html</code>，访问地址就得变成 <code>http://localhost/dist/</code>——和 PPT 上写的 <code>http://localhost:80</code> 就对不上了。</p><p>nginx 目录里都有什么（第 26 页那张图给每个文件夹标了中文注释）：</p><p><img src="https://img.tsh520.cn/file/blog/article/26-nginx%E7%9B%AE%E5%BD%95%E7%BB%93%E6%9E%84.jpg" alt="nginx 安装目录的结构"><em>图：PPT 第 26 页配的 nginx 安装目录——<code>conf</code>（<strong>配置文件目录</strong>，<code>nginx.conf</code> 就在里面）、<code>contrib</code>、<code>docs</code>、<strong><code>html</code>（静态资源文件存放目录，html、CSS、JS 都放这儿）</strong>、<code>logs</code>（日志文件存放目录）、<code>temp</code>（临时文件存放目录），最下面是可执行文件 <strong><code>nginx.exe</code></strong>。第①步把打包产物放进 <code>html</code>，第②步双击的就是这个 <code>nginx.exe</code></em></p><p>第③步打开浏览器之后看到什么？——<strong>和开发时一模一样的 Tlias 页面</strong>：</p><p><img src="https://img.tsh520.cn/file/blog/article/27-%E8%AE%BF%E9%97%AElocalhost%E7%9C%8B%E5%88%B0%E7%9A%84%E9%A6%96%E9%A1%B5.jpg" alt="访问 localhost 看到的首页"><em>图：PPT 第 27 页配的&quot;访问 <code>http://localhost:80</code>&quot;效果——左边是首页、班级学员管理、系统信息管理、数据统计管理四个菜单，右上角&quot;修改密码 | 退出登录【宋江】&quot;，中间是&quot;教学后台&quot;那张插画。这个页面就是你打包出来的 <code>index.html</code> + <code>assets</code> 渲染的结果，由 nginx 这个&quot;静态 Web 服务器&quot;从 80 端口发出来——<strong>路径里没有 5173、也没有 vite</strong>，说明它真的是一份独立的前端产物</em></p><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>这一步里还有一个&quot;看不见但必须有&quot;的前提：<strong>后端也得起着</strong>（<a href="/posts/编程学习/javaweb学习笔记/57-tlias项目准备与开发规范/">57 篇</a>那套 SpringBoot 工程，打成 jar 跑在自己端口上，本课程是 8080）。前端只是页面，数据还得到后端去取——所以真正上线是&quot;前端静态文件 + 后端 jar&quot;两样都部署。PPT 这里只讲前端那一半。</p></div><h2 id="_80-端口被占用怎么办-ppt-第-27-页的-注意" tabindex="-1">80 端口被占用怎么办（PPT 第 27 页的&quot;注意&quot;） <a class="header-anchor" href="#_80-端口被占用怎么办-ppt-第-27-页的-注意" aria-label="Permalink to &quot;80 端口被占用怎么办（PPT 第 27 页的&quot;注意&quot;）&quot;">​</a></h2><p>第 27 页末尾专门留了一条&quot;注意&quot;：</p><blockquote><p><strong>注意</strong>：Nginx 默认占用 80 端口号，如果 80 端口号被占用，可以在 <strong>nginx.conf</strong> 中修改端口号。（<code>netstat –ano | findStr 80</code>）</p></blockquote><p>为什么要专门提这一条？因为 <strong>80 端口是浏览器默认的 HTTP 端口</strong>——地址里不写端口时走的就是它，所以 <code>http://localhost:80</code> 可以直接写成 <code>http://localhost</code>。反过来说，80 也是个&quot;抢手&quot;端口：IIS、某些开发工具、别的 Web 服务都爱占它，一旦被占，nginx <strong>起不来</strong>（现象往往是&quot;双击了 nginx.exe 却什么都没发生&quot;、浏览器打不开页面）。</p><p>排查和处理分三步：</p><ol><li><strong>查是谁占了 80</strong>：命令行执行 <code>netstat -ano | findStr 80</code>（PPT 上写的 <code>netstat –ano | findStr 80</code>）——<code>netstat</code> 列出网络连接和端口占用情况，<code>-ano</code> 让输出带上&quot;进程号 PID&quot;，<code>| findStr 80</code> 把跟 80 有关的行筛出来；拿到 PID 后到<strong>任务管理器 → 详细信息</strong>里对一下是哪个程序。</li><li><strong>改 nginx 的端口</strong>：打开 nginx 安装目录下的 <strong><code>conf/nginx.conf</code></strong>，找到 <code>server</code> 块里的 <code>listen 80;</code>，改成别的端口（比如 90）。</li><li><strong>按新端口访问</strong>：重载（或重启）nginx 之后，浏览器里改成 <code>http://localhost:90</code>（端口不是 80 时<strong>必须写出来</strong>）。</li></ol><p>改的就是这一段：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ← 被占用的就是这里，改一个没被用的端口</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> localhost;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        root </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  html;                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 静态文件目录：打包产物放在这儿（第①步的落点）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        index </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index.html index.htm;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>这里的&quot;改端口&quot;和 <a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>里那次是同一件事：<strong>第 7 章那份 nginx 配的就是 <code>listen 90;</code></strong>，所以访问地址写成了 <code>http://localhost:90</code>。改完配置<strong>必须让 nginx 重新读配置</strong>才生效——用下面的重载命令。</p></div><h2 id="三条命令-ppt-第-28-页" tabindex="-1">三条命令（PPT 第 28 页） <a class="header-anchor" href="#三条命令-ppt-第-28-页" aria-label="Permalink to &quot;三条命令（PPT 第 28 页）&quot;">​</a></h2><p>PPT 第 28 页把整节收成一张小结（这是最该背下来的一页）：</p><blockquote><p><strong>前端项目的打包部署</strong></p><ul><li><strong>打包</strong>：运行 build ---&gt; dist</li><li><strong>部署</strong>：将 dist 目录下的打包好的文件 ---&gt; nginx/html 目录中</li><li><strong>nginx 命令</strong>： <ul><li><strong>启动</strong>：<code>nginx.exe</code></li><li><strong>重载</strong>：<code>nginx.exe -s reload</code></li><li><strong>停止</strong>：<code>nginx.exe -s stop</code></li></ul></li></ul></blockquote><table tabindex="0"><thead><tr><th>命令</th><th>什么意思</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>nginx.exe</code></td><td><strong>启动</strong>：起 nginx 服务（Windows 下双击也行）</td><td>第一次起服务；<code>-s stop</code> 停掉之后要重新起</td></tr><tr><td><code>nginx.exe -s reload</code></td><td><strong>重载</strong>：让 nginx 重新读一遍 <code>conf/nginx.conf</code>，<strong>不停服务</strong>就换上新配置</td><td><strong>改了 <code>nginx.conf</code>（比如换了端口）之后必须执行</strong>；换了 <code>html</code> 里的页面文件后也顺手 reload 一下最稳</td></tr><tr><td><code>nginx.exe -s stop</code></td><td><strong>停止</strong>：关掉 nginx（干掉它的进程）</td><td>不想让它继续跑、或者要腾端口的时候</td></tr></tbody></table><p>三个使用细节（<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>踩过的同款）：</p><ol><li><strong>命令要在 nginx 的安装目录里执行</strong>（<code>nginx.exe</code> 所在的那个目录），否则系统找不到这个命令；</li><li>Windows 版 nginx 是<strong>绿色免安装</strong>的，双击启动后<strong>没有窗口、没有托盘图标</strong>，它就在后台跑着——&quot;有没有起来&quot;要靠浏览器访问或任务管理器看进程；</li><li>三条命令里&quot;重载&quot;是最常用的：改了配置<strong>不重载等于没改</strong>，页面表现还和以前一模一样（容易以为&quot;改了没用&quot;）。</li></ol><h2 id="一个-ppt-没提、但迟早要撞上的问题-补充" tabindex="-1">一个 PPT 没提、但迟早要撞上的问题（补充） <a class="header-anchor" href="#一个-ppt-没提、但迟早要撞上的问题-补充" aria-label="Permalink to &quot;一个 PPT 没提、但迟早要撞上的问题（补充）&quot;">​</a></h2><p>到这里，按 PPT 的步骤：<strong>打包 → 复制到 html → 启动 nginx → 访问 <code>http://localhost</code></strong>，页面确实能打开了。但页面打开之后，它做的事和开发时一样——<strong>发请求取数据</strong>（比如员工管理页一进去就查列表）。而这些请求的地址是 <code>/api/emps?...</code>（<a href="/posts/编程学习/javaweb学习笔记/99-部门管理-列表查询/">99 篇</a>在 <code>request.js</code> 里配的 <code>baseURL: &#39;/api&#39;</code>）。</p><p>问题来了：</p><table tabindex="0"><thead><tr><th>阶段</th><th><code>/api/...</code> 的请求会打到哪</th><th>结果</th></tr></thead><tbody><tr><td>开发阶段（<code>npm run dev</code>）</td><td>Vite 开发服务器的<strong>代理</strong>把它转发给后端（<code>vite.config.js</code> 的 <code>server.proxy</code>）</td><td>正常拿到数据</td></tr><tr><td>上线之后（nginx 的 80）</td><td><strong>nginx</strong>——而 nginx 按当前配置只会去 <code>html</code> 目录里找 <code>/api/emps</code> 这个&quot;文件&quot;</td><td>找不到 → <strong>404</strong></td></tr></tbody></table><p>也就是说，<strong>打好了包、放进了 html、nginx 也起来了，页面能看，但数据全是空的</strong>。要补的那一步在第 7 章其实做过：给 nginx 加一段<strong>反向代理</strong>，把 <code>/api</code> 开头的请求转给后端（<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>逐行拆过 <code>location ^~ /api/</code>、<code>rewrite</code>、<code>proxy_pass</code> 三行）：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 【补充】把前端发来的 /api 请求转发给后端（不在 PPT 第 18 章里，参照 59 篇）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ^~</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> /api/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        rewrite</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> ^/api/(.*)$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /$1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">break</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 摘掉 /api 前缀（后端接口路径里没有 /api）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:8080;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 转给后端服务</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p>这一段<strong>PPT 第 21～28 页里没有</strong>，是本站补的——理由很实在：第 18 章的部署演示大概率是<strong>只验&quot;页面能不能打开&quot;</strong>，而&quot;页面里的数据从哪来&quot;这个问题在第 7 章已经用反向代理解决过一次（<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>，那次访问的是 90 端口）。把两章接起来看，&quot;上线&quot;这套东西其实是 <strong>静态托管（nginx 发页面）+ 反向代理（nginx 转 /api 给后端）</strong> 两件事一起做。真要照这一篇上线，记得把这段补上，并确认 <code>proxy_pass</code> 的端口和后端实际起的端口一致。</p></div><h2 id="班级管理-学员管理-ppt-第-29-页" tabindex="-1">班级管理 &amp; 学员管理（PPT 第 29 页） <a class="header-anchor" href="#班级管理-学员管理-ppt-第-29-页" aria-label="Permalink to &quot;班级管理 &amp; 学员管理（PPT 第 29 页）&quot;">​</a></h2><p>第 29 页只有一行字：&quot;<strong>班级管理 &amp; 学员管理</strong>&quot;，配两张成品截图——这两个页面是课程留给学员<strong>自己实现</strong>的（PPT 里没给步骤）。后端那两套接口在 <a href="/posts/编程学习/javaweb学习笔记/78-项目实战-班级管理/">78 篇</a>、<a href="/posts/编程学习/javaweb学习笔记/79-项目实战-学员管理/">79 篇</a>里已经做过。</p><p><img src="https://img.tsh520.cn/file/blog/article/29-%E7%8F%AD%E7%BA%A7%E7%AE%A1%E7%90%86%E9%A1%B5.jpg" alt="班级管理页面"><em>图：PPT 第 29 页配的班级管理页——顶部是条件查询表单（班级名称输入框 + 结课时间范围 + &quot;查询 / 清空&quot;），下面绿色&quot;+ 新增班级&quot;按钮，表格九列（序号 / 班级名称 / 班级教室 / 班主任 / 开课时间 / 结课时间 / 状态 / 最后修改时间 / 操作），操作列里每行&quot;编辑 / 删除&quot;，底部&quot;共 6 条&quot;的分页条。<strong>结构和员工管理页一个套路</strong>：条件查询 + 新增 + 修改 + 删除</em></p><p><img src="https://img.tsh520.cn/file/blog/article/29-%E5%AD%A6%E5%91%98%E7%AE%A1%E7%90%86%E9%A1%B5.jpg" alt="学员管理页面"><em>图：PPT 第 29 页配的学员管理页——条件查询（姓名 / 最高学历 / 所属班级 + &quot;查询 / 清空&quot;），绿色&quot;+ 新增学员&quot;和红色&quot;- 批量删除&quot;两个按钮，表格最左边是复选框列、每行操作列有&quot;编辑 / 违纪 / 删除&quot;三个按钮，底部&quot;共 18 条&quot;分页条。<strong>批量删除那一套（复选框收集 id）就是 <a href="/posts/编程学习/javaweb学习笔记/103-员工管理-修改与删除/">103 篇</a>做过的东西</strong></em></p><p>自己实现时的&quot;照葫芦画瓢&quot;路径：接口照 <a href="/posts/编程学习/javaweb学习笔记/78-项目实战-班级管理/">78</a>、<a href="/posts/编程学习/javaweb学习笔记/79-项目实战-学员管理/">79 篇</a>的接口文档封进 <code>src/api/</code>；页面结构对着上面两张截图；交互照员工管理那一套（<a href="/posts/编程学习/javaweb学习笔记/101-员工管理-条件分页查询/">101</a>～<a href="/posts/编程学习/javaweb学习笔记/103-员工管理-修改与删除/">103 篇</a>）。</p><p>第 30 页是一张<strong>空白页</strong>——第 18 章到此结束，Tlias 的前端实战这一段也就收官了。再往后（第 19 章起）就是把项目搬到真正的服务器上去的章节（Linux、Docker，见 <a href="/posts/编程学习/javaweb学习笔记/95-前端工程化与vue项目/">95 篇</a>开头那张全景表）——那是&quot;部署&quot;这两个字的下一个层次。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>为什么前端要打包？</td><td>服务器上不会给你开 Vite 开发服务器；用户要的是&quot;打开网址就能看页面&quot;，所以工程要先变成<strong>浏览器能直接认的静态文件</strong>（html + css + js），再交给 Web 服务器发出去</td></tr><tr><td>打包命令与产物？</td><td>在工程根目录执行 <strong><code>npm run build</code></strong>（本课程工程里这个脚本就是 <code>vite build</code>），产出 <strong><code>dist</code></strong> 目录：<code>index.html</code> + <code>assets/</code>（js、css）+ <code>favicon.ico</code></td></tr><tr><td>打包做了哪三件事？</td><td>编译（<code>.vue</code> 等浏览器不认的语法转成 JS）、合并压缩（上百个模块合成几个文件、去掉多余字符）、产出纯静态文件（不需要 Node/Vite 也能跑）</td></tr><tr><td>Nginx 是什么？</td><td><strong>轻量级 Web 服务器 / 反向代理服务器</strong>；特点<strong>占有内存少、并发能力强</strong>；官网 <a href="https://nginx.org/" target="_blank" rel="noreferrer">https://nginx.org/</a></td></tr><tr><td>nginx 的两个身份分别用在哪？</td><td><strong>Web 服务器</strong>（本篇：发前端静态文件）；<strong>反向代理</strong>（<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>：把 <code>/api</code> 请求转给后端）</td></tr><tr><td>部署三步？</td><td>① 把 <strong><code>dist</code> 里的文件</strong>复制到 nginx 的 <strong><code>html</code></strong> 目录 ② 双击 <strong><code>nginx.exe</code></strong> 启动（默认 <strong>80</strong> 端口）③ 浏览器访问 <strong><code>http://localhost:80</code></strong>（即 <code>http://localhost</code>）</td></tr><tr><td>nginx 目录里哪些要记？</td><td><code>conf</code>（配置，<code>nginx.conf</code>）、<strong><code>html</code>（静态资源，打包产物的落点）</strong>、<code>logs</code>（日志）、<code>nginx.exe</code>（可执行文件）</td></tr><tr><td>80 端口被占用怎么办？</td><td>先查 <code>netstat -ano | findStr 80</code> 找出占用进程；再改 <strong><code>conf/nginx.conf</code></strong> 里 <code>listen 80;</code>（比如 90）；重载后按新端口访问 <code>http://localhost:90</code></td></tr><tr><td>三条命令？</td><td>启动 <strong><code>nginx.exe</code></strong>、重载 <strong><code>nginx.exe -s reload</code></strong>、停止 <strong><code>nginx.exe -s stop</code></strong>；命令要在 nginx 安装目录里执行，<strong>改了 <code>nginx.conf</code> 必须 reload</strong></td></tr><tr><td>打包部署完页面能开但没数据，为什么？</td><td>上线后没有 Vite 的代理了，<code>/api</code> 请求打到了 nginx 上、被当成静态文件找不到（404）——要照 <a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>补一段 <code>location ^~ /api/</code> + <code>rewrite</code> + <code>proxy_pass</code> 的反向代理（PPT 没讲，属于本站补充）</td></tr><tr><td>这一篇的实测情况？</td><td><strong>打包与 nginx 部署本轮没有实测</strong>；可参照 <a href="/posts/编程学习/javaweb学习笔记/95-前端工程化与vue项目/">95 篇</a>（同版本工程的 <code>npm run build</code> 与 dist 产物大小）和 <a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>（Windows 版 nginx 起 90 端口 + 反向代理的实测）</td></tr><tr><td>第 29 页说的班级管理、学员管理呢？</td><td>课程明确留给学员<strong>自己实现</strong>（第 18 章不演示）；页面结构照 PPT 那两张截图，交互照员工管理那一套</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/104-登录退出与令牌管理/">上一篇：登录退出与令牌管理</a></li><li><a href="/posts/编程学习/javaweb学习笔记/106-linux概述与系统安装/">下一篇：Linux概述与系统安装</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li><strong>为什么要打包</strong>：开发阶段靠 Vite 开发服务器（默认 5173）+ <code>vite.config.js</code> 里的代理跑；<strong>上线时服务器上不会有这东西</strong>，前端必须先变成浏览器能直接认的静态文件，再交给 Web 服务器发出去</li><li><strong>打包命令</strong>：到工程根目录（有 <code>package.json</code> 的那层）执行 <strong><code>npm run build</code></strong>（本课程工程的 <code>build</code> 脚本 = <code>vite build</code>），产物是 <strong><code>dist</code></strong> 目录</li><li><strong><code>dist</code> 里有什么</strong>：<code>index.html</code>、<code>assets/</code>（编译压缩后的 js、css 等）、<code>favicon.ico</code>——就是&quot;一个 html + 一堆资源&quot;，源码和 <code>node_modules</code> 都不用带</li><li><strong>打包干的三件事</strong>：编译（<code>.vue</code>/组合式 API 等转成普通 JS）、合并压缩（上百模块合成几个文件）、产出<strong>纯静态文件</strong>（不需要 Node、不需要 Vite）</li><li>打包体积可以和 <a href="/posts/编程学习/javaweb学习笔记/95-前端工程化与vue项目/">95 篇</a>的实测对照：<code>index.html</code> 0.42 KiB、<code>index.css</code> 316.98 KiB、<code>index.js</code> 877.21 KiB，还有 <code>chunks are larger than 500 KiB</code> 的提示（ElementPlus 全量引入所致）</li><li><strong>Nginx 是什么</strong>：轻量级的 <strong>Web 服务器 / 反向代理服务器</strong>及电子邮件（IMAP/POP3）代理服务器；特点是<strong>占有内存少、并发能力强</strong>；官网 <a href="https://nginx.org/" target="_blank" rel="noreferrer">https://nginx.org/</a> ；两个身份本站都见过——<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>用的是&quot;反向代理&quot;，本篇用的是&quot;Web 服务器&quot;</li><li><strong>部署三步</strong>（PPT 第 26～27 页）：① 把 <strong><code>dist</code> 目录下的文件</strong>复制到 nginx 安装目录的 <strong><code>html</code></strong> 目录里 ② <strong>双击 <code>nginx.exe</code></strong> 启动（默认占用 <strong>80</strong> 端口）③ 浏览器访问 <strong><code>http://localhost:80</code></strong>（= <code>http://localhost</code>）</li><li><strong>nginx 目录结构</strong>：<code>conf</code>（配置文件目录，<code>nginx.conf</code> 在这里）、<code>contrib</code>、<code>docs</code>、<strong><code>html</code>（静态资源文件存放目录，html/css/js 放这儿）</strong>、<code>logs</code>（日志）、<code>temp</code>（临时文件）、<code>nginx.exe</code>（可执行文件）</li><li><strong>80 端口被占用的处理</strong>：查占用用 <code>netstat -ano | findStr 80</code>（拿到 PID 去任务管理器对程序）；改端口改 <strong><code>conf/nginx.conf</code></strong> 里 <code>server</code> 块的 <code>listen 80;</code>；重载/重启后按新端口访问（<code>http://localhost:90</code>）——<a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>那份 nginx 就是 90</li><li><strong>三条命令</strong>（PPT 第 28 页）：启动 <code>nginx.exe</code>、重载 <code>nginx.exe -s reload</code>、停止 <code>nginx.exe -s stop</code>；命令在 nginx 安装目录里执行；<strong>改了 <code>nginx.conf</code> 必须 reload 才生效</strong>；Windows 版双击启动后没有窗口，靠浏览器/任务管理器确认</li><li><strong>一个补充</strong>：打包上线后 <code>/api</code> 请求会打到 nginx 上（没有 Vite 代理了），要在 <code>nginx.conf</code> 里照 <a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>加 <code>location ^~ /api/</code> + <code>rewrite ^/api/(.*)$ /$1 break;</code> + <code>proxy_pass http://localhost:8080;</code> 才能真正取到数据（PPT 第 21～28 页没讲）</li><li><strong>本轮实测边界</strong>：打包与 nginx 部署<strong>没有实测</strong>；可参照第 95 篇（同版本工程的 <code>npm run build</code> 与 dist 大小）和第 59 篇（nginx 起 90 端口 + 反向代理）；第 29 页的班级管理、学员管理是&quot;自己实现&quot;，本轮不涉及</li></ol><h3 id="二、裸写题" tabindex="-1">二、裸写题 <a class="header-anchor" href="#二、裸写题" aria-label="Permalink to &quot;二、裸写题&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 把工程变成一份能交给服务器的文件</strong> 需求：假设你的前端工程在 <code>D:\\code\\vue-tlias-management</code>，现在要交给服务器。请写出：① 在哪个目录、执行哪条命令来做&quot;打包&quot;；② 打包产出的文件夹叫什么、里面主要有哪些东西；③ 为什么不能直接把 <code>src</code>、<code>node_modules</code> 拷给服务器；④ 打包结果需不需要 Node 环境才能跑。 素材：工程的 <code>package.json</code> 里 <code>scripts</code> 段有 <code>dev</code>、<code>build</code>、<code>preview</code>、<code>lint</code> 四条脚本。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：打包是&quot;把源码翻译成浏览器能认的东西&quot;，翻译的入口写在 <code>package.json</code> 的脚本里；命令要在工程根目录（<code>package.json</code> 所在的那层）执行，产出固定是那个文件夹 <strong>二级 · 方法</strong>：命令是 <strong><code>npm run build</code></strong>（这个脚本的实际内容 <code>vite build</code>）；产物目录 <strong><code>dist</code></strong>，里面有 <code>index.html</code>、<code>assets/</code>（js、css）、<code>favicon.ico</code>；<code>src</code> 是源码（浏览器不认 <code>.vue</code>、也不认一个个小模块）、<code>node_modules</code> 是开发用的依赖包（体积巨大且运行期不需要） <strong>三级 · 骨架</strong>：① 目录：<code>____</code>（有 package.json 的那层）；命令：<code>____</code>；② 产物目录：<code>____</code>，里面有 <code>____</code>、<code>____</code>；③ 因为源码浏览器不认识、依赖包运行时用不上；④ <code>dist</code> 是<strong>纯静态文件</strong>，交给任何静态服务器（nginx）就能发，<strong>不需要 Node/Vite</strong></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 目录：D:\\code\\vue-tlias-management（工程根目录，有 package.json 的那一层）</span></span>
<span class="line"><span>   命令：npm run build</span></span>
<span class="line"><span>   （本课程工程里 build 脚本的实际内容是 vite build）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 产物：dist 目录</span></span>
<span class="line"><span>   dist/</span></span>
<span class="line"><span>   ├── assets/              编译压缩后的 js、css 等</span></span>
<span class="line"><span>   ├── favicon.ico          站点图标</span></span>
<span class="line"><span>   └── index.html           入口页面</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 不能直接拷 src / node_modules 的原因：</span></span>
<span class="line"><span>   · src 是源码：.vue 文件、组合式 API、模板语法浏览器都不认识，必须编译；</span></span>
<span class="line"><span>   · 上百个模块要合并压缩后才适合在网络上传输；</span></span>
<span class="line"><span>   · node_modules 是开发期依赖包，体积巨大，运行期用不到。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ dist 是纯静态文件（html + css + js + 图片），</span></span>
<span class="line"><span>   不需要 Node、不需要 Vite，交给 nginx 这类静态服务器就能访问。</span></span></code></pre></div><p>检查点：① 命令写的是 <code>npm run build</code>（不是 <code>npm run dev</code>）；② 产物是 <code>dist</code>（不是 <code>src</code>、不是 <code>public</code>）；③ 能说清楚&quot;编译 + 压缩 + 纯静态&quot;这三层理由；④ 知道 <a href="/posts/编程学习/javaweb学习笔记/95-前端工程化与vue项目/">95 篇</a>里跑过同一条命令、产物大小是多少。</p></details></li><li><p>[ ] <strong>2-2 把打包产物部署到 nginx 上并访问</strong> 需求：手上有一台 Windows 机器，装好了一份绿色版 nginx（目录里有 <code>conf</code>、<code>html</code>、<code>logs</code>、<code>temp</code> 和 <code>nginx.exe</code>），也已经打包出了 <code>dist</code>。请写出从&quot;放文件&quot;到&quot;浏览器里看到页面&quot;的完整步骤（每一步写清楚动作 + 落点），并说明：① 为什么是放到那个目录；② 启动之后浏览器该访问什么地址；③ 后端要不要一起起。 素材：nginx 默认监听 80 端口；<code>conf/nginx.conf</code> 里 <code>location / { root html; index index.html index.htm; }</code>。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：三件事——<strong>放文件</strong>（放到 nginx 认的那个静态根目录里）、<strong>起服务</strong>（运行 nginx 的可执行文件）、<strong>访问</strong>（浏览器默认端口）。放文件时要注意层次：nginx 是拿那个目录当&quot;根&quot;去找 <code>index.html</code> 的 <strong>二级 · 方法</strong>：把 <code>dist</code> <strong>里面的文件</strong>（<code>index.html</code>、<code>assets/</code>、<code>favicon.ico</code>）复制到 nginx 安装目录的 <strong><code>html</code></strong> 目录下；双击（或命令行运行）<strong><code>nginx.exe</code></strong>；浏览器访问 <strong><code>http://localhost</code></strong>（等同 <code>http://localhost:80</code>）；后端还是要单独起自己的服务（课件里是 SpringBoot 打 jar 跑 8080），否则页面能开但取不到数据 <strong>三级 · 骨架</strong>：① 复制 <code>dist</code> 里的文件 → nginx 的 <code>____</code> 目录；② 运行 <code>____</code>；③ 访问 <code>http://____</code>；④ 后端<strong>也要起</strong>（不然页面能看、数据取不到）</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 部署（放文件）</span></span>
<span class="line"><span>   把 dist 目录下的文件——index.html、assets/、favicon.ico——</span></span>
<span class="line"><span>   复制到 nginx 安装目录的 html 目录下。</span></span>
<span class="line"><span>   （注意是 dist 里面的东西，不是把 dist 文件夹整个塞进 html）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 启动（起服务）</span></span>
<span class="line"><span>   到 nginx 安装目录，双击 nginx.exe（或命令行执行 nginx.exe）。</span></span>
<span class="line"><span>   nginx 默认占用 80 端口；启动后没有窗口，在后台跑。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 访问</span></span>
<span class="line"><span>   浏览器打开 http://localhost:80（也就是 http://localhost）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ 后端</span></span>
<span class="line"><span>   要一起起（SpringBoot 打 jar 跑自己的端口，课程里是 8080）；</span></span>
<span class="line"><span>   前端只是页面，数据还得到后端去取。</span></span></code></pre></div><p>检查点：① 顺序是&quot;放文件 → 起 nginx → 访问&quot;（不是先访问再放文件）；② 落点是 <strong><code>html</code> 目录</strong>、复制的是 <code>dist</code> <strong>里面的文件</strong>（不嵌套一层）；③ 访问地址写 <code>http://localhost</code>（80 可省）；④ 知道后端要另起；⑤ 能顺嘴说出 <code>html</code> 目录在 nginx 里是&quot;静态资源文件存放目录&quot;（PPT 第 26 页那张图的注释）。</p></details></li><li><p>[ ] <strong>2-3 nginx 起不来——80 端口被别的程序占了</strong> 需求：双击 <code>nginx.exe</code> 之后浏览器打不开 <code>http://localhost</code>，怀疑 80 端口被占用。请写出：① 用什么命令查出到底是哪个进程占了 80 端口（以及怎么看出进程号）；② 改哪个文件的哪个位置能换端口（写出改前改后的样子）；③ 改完之后要做什么才能生效；④ 换成 90 端口之后浏览器该访问什么地址。 素材：nginx 的配置文件是 <code>conf/nginx.conf</code>，里面有个 <code>server</code> 块；Windows 下可以用任务管理器对进程号。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先&quot;抓到占端口的人&quot;，再&quot;给 nginx 换个门牌号&quot;，然后&quot;让 nginx 重新读一遍配置&quot;，最后&quot;按新门牌号访问&quot;。门牌号写在配置文件里，改配置不重载等于没改 <strong>二级 · 方法</strong>：查占用 <code>netstat -ano | findStr 80</code>（<code>-ano</code> 会带上 PID，拿 PID 去任务管理器对）；改 <code>conf/nginx.conf</code> 里 <code>server</code> 块的 <code>listen 80;</code> → <code>listen 90;</code>；用 <strong><code>nginx.exe -s reload</code></strong> 重载（或先 stop 再启动）；访问改成 <code>http://localhost:90</code><strong>三级 · 骨架</strong>：① 查：<code>____ -ano | findStr ____</code>；② 改 <code>conf/____</code> 里的 <code>listen ____;</code> → <code>listen 90;</code>；③ 生效：<code>nginx.exe -s ____</code>；④ 访问：<code>http://localhost:____</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 查占用：</span></span>
<span class="line"><span>   netstat -ano | findStr 80</span></span>
<span class="line"><span>   · -a 列出所有连接与监听端口，-n 用数字显示地址和端口，-o 显示占用它的进程号（PID）</span></span>
<span class="line"><span>   · 找到 PID 后到「任务管理器 → 详细信息」里对一下是哪个程序</span></span>
<span class="line"><span>   （PPT 第 27 页给的就是 netstat –ano | findStr 80）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 改端口（conf/nginx.conf 的 server 块）：</span></span>
<span class="line"><span>   server {</span></span>
<span class="line"><span>       listen       80;      ← 改成 listen       90;</span></span>
<span class="line"><span>       server_name  localhost;</span></span>
<span class="line"><span>       location / {</span></span>
<span class="line"><span>           root   html;</span></span>
<span class="line"><span>           index  index.html index.htm;</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 生效：</span></span>
<span class="line"><span>   nginx.exe -s reload     （改完 nginx.conf 必须重载；也可以先 nginx.exe -s stop 再启动）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ 访问：</span></span>
<span class="line"><span>   http://localhost:90     （端口不是 80 时，地址里必须写出来）</span></span></code></pre></div><p>检查点：① 命令是 <code>netstat -ano | findStr 80</code>（能说出 <code>-ano</code> 里有&quot;显示进程号&quot;的作用）；② 改的是 <code>conf/nginx.conf</code> 里 <code>server</code> 块的 <code>listen</code>（不是别的地方）；③ 知道改完<strong>必须 reload</strong>（不重载的话现象和改之前一模一样）；④ 访问地址带上新端口；⑤ 联想 <a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>那份 nginx 就是 <code>listen 90;</code>。</p></details></li><li><p>[ ] <strong>2-4 nginx 的三条命令分别什么时候用</strong> 需求：请写出 nginx 在 Windows 下的<strong>启动 / 重载 / 停止</strong>三条命令，并针对下面四种情形各挑一条命令说明理由——① 第一次把 nginx 跑起来；② 把 <code>listen 80;</code> 改成了 <code>listen 90;</code>；③ 前端重新打包了，换掉了 <code>html</code> 目录里的 <code>index.html</code> 和 <code>assets</code>；④ 想腾出端口给别的程序，先让 nginx 别再占着。另外说明：这些命令要在什么目录里执行、启动后怎么确认它真的在跑。 素材：nginx 是绿色免安装的，可执行文件叫 <code>nginx.exe</code>。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：三条命令是&quot;起 / 换口气 / 停&quot;——改配置那件事只有&quot;换口气&quot;（重载）能办到，而且它不停服务；纯替换静态文件一般刷新浏览器就行，但顺手重载最稳 <strong>二级 · 方法</strong>：启动 <code>nginx.exe</code>、重载 <code>nginx.exe -s reload</code>、停止 <code>nginx.exe -s stop</code>（PPT 第 28 页原文）；命令要在 <strong>nginx 安装目录</strong>（<code>nginx.exe</code> 所在目录）里执行；Windows 版启动后<strong>没有窗口</strong>，靠浏览器访问或任务管理器里的 <code>nginx</code> 进程确认 <strong>三级 · 骨架</strong>：① <code>____</code>；② <code>nginx.exe -s ____</code>；③ 刷新浏览器即可 / 稳妥做法还是 <code>____</code>；④ <code>nginx.exe -s ____</code>；执行位置：<code>____</code> 目录</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三条命令（PPT 第 28 页）：</span></span>
<span class="line"><span>  启动：nginx.exe</span></span>
<span class="line"><span>  重载：nginx.exe -s reload</span></span>
<span class="line"><span>  停止：nginx.exe -s stop</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① 第一次起服务 → 启动：nginx.exe（双击也行）</span></span>
<span class="line"><span>② 改了 listen 80 → 90 → 重载：nginx.exe -s reload</span></span>
<span class="line"><span>   （改的是 conf/nginx.conf，不重载不生效；重载不用停服务）</span></span>
<span class="line"><span>③ 换了 html 里的 index.html / assets → 刷新浏览器一般就能看到；</span></span>
<span class="line"><span>   稳妥做法还是 nginx.exe -s reload</span></span>
<span class="line"><span>④ 想腾出端口 → 停止：nginx.exe -s stop</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行位置：nginx 的安装目录（nginx.exe 所在目录），否则找不到命令。</span></span>
<span class="line"><span>确认在跑：浏览器访问 http://localhost[:端口]；或任务管理器里找 nginx 进程</span></span>
<span class="line"><span>（Windows 版双击启动后没有窗口、没有托盘图标）。</span></span></code></pre></div><p>检查点：① 三条命令一字不错（尤其 <code>-s reload</code> / <code>-s stop</code> 的 <code>-s</code>）；② 情形②必须选&quot;重载&quot;而不是&quot;停止&quot;（重载能不停服务换配置）；③ 知道命令要在 nginx 安装目录执行；④ 知道 Windows 版 nginx 启动后&quot;看不见窗口&quot;，要另找办法确认。</p></details></li></ul><h3 id="三、综合题" tabindex="-1">三、综合题 <a class="header-anchor" href="#三、综合题" aria-label="Permalink to &quot;三、综合题&quot;">​</a></h3><ul><li><p>[ ] <strong>3-1 把&quot;从源码到浏览器访问&quot;这条路走一遍（并把它写成清单）</strong> 需求：照着 PPT 第 21～28 页，把你自己的 Tlias 前端工程从&quot;源码&quot;一路做到&quot;浏览器访问 <code>http://localhost</code> 能看到页面&quot;，并把整个过程写成一份可以照着做的清单（每一步写清&quot;在哪儿、做什么、怎么确认成功&quot;）。分步做：</p><ol><li><strong>先确认前提</strong>：工程能正常开发跑（<code>npm run dev</code>）、后端能起（数据接口能通）；记下两者各自的端口</li><li><strong>打包</strong>：到工程根目录执行打包命令，确认产出目录和里面的文件（<code>index.html</code>、<code>assets/</code>）</li><li><strong>准备 nginx</strong>：确认机器上有一份 nginx，认清它的目录（配置文件在哪、静态目录在哪、可执行文件在哪）；如果 80 端口已经被占，先把它查出来</li><li><strong>部署</strong>：把打包产物里的文件放到 nginx 的静态目录里；如果换了端口，改配置文件里监听的那一行</li><li><strong>启动与生效</strong>：起 nginx（改了配置就让它重载）；确认服务真的在跑</li><li><strong>访问验证</strong>：浏览器打开对应地址，确认页面显示出来（菜单、页面标题、登录页都在）</li><li><strong>再想一层</strong>：页面能开了，但数据从哪来？把&quot;上线后 <code>/api</code> 请求该由谁转发、怎么配&quot;这一步补进清单（提示：第 7 章 <a href="/posts/编程学习/javaweb学习笔记/59-部门管理-前后端联调与反向代理/">59 篇</a>做过）</li><li><strong>收尾</strong>：把自己的清单和 PPT 第 28 页那一页小结对一遍（打包 / 部署 / 三条命令），看有没有漏项</li></ol><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：这条链路的四站是——<strong>工程（源码）→ dist（产物）→ nginx 的 html（部署）→ 浏览器（访问）</strong>；每一站都问自己&quot;东西进了哪个目录、由谁读它&quot;。第 7 步是这道题的重点：页面归 nginx 发，接口得有人转 <strong>二级 · 方法</strong>：<code>npm run build</code> 出 <code>dist</code>；把 <code>dist</code> 里的文件复制到 nginx 的 <code>html</code>；双击 <code>nginx.exe</code> 启动（默认 80）、改过 <code>nginx.conf</code> 就 <code>nginx.exe -s reload</code>；访问 <code>http://localhost</code>；上线后的 <code>/api</code> 请求用 <code>location ^~ /api/</code> + <code>rewrite ^/api/(.*)$ /$1 break;</code> + <code>proxy_pass http://localhost:8080;</code> 转给后端 <strong>三级 · 骨架</strong>：清单四段——① 打包（<code>____</code> → <code>dist</code>）② 部署（<code>dist</code> 里文件 → <code>nginx/____</code>）③ 启动（<code>____</code>，改了配置用 <code>nginx.exe -s ____</code>）④ 访问（<code>http://localhost[:____]</code>）＋ ⑤ 补充：<code>/api</code> 交给 <code>____</code>（<code>location ____ /api/</code>）</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>清单：从源码到浏览器访问</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【0】前提确认</span></span>
<span class="line"><span>  · 前端：npm run dev 能起来（开发端口 5173，或日志里实际用的那个）</span></span>
<span class="line"><span>  · 后端：SpringBoot 工程已启动（课程里 8080；本机因 8080 被占改成了 8081）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【1】打包（PPT 第 24 页）</span></span>
<span class="line"><span>  · 位置：前端工程根目录（有 package.json 的那层）</span></span>
<span class="line"><span>  · 命令：npm run build      （= vite build）</span></span>
<span class="line"><span>  · 产物：dist/ → index.html、assets/（js、css）、favicon.ico</span></span>
<span class="line"><span>  · 确认成功：命令行没有报错，dist 目录里确实有上面这些文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【2】准备 nginx（PPT 第 25～26 页）</span></span>
<span class="line"><span>  · 认清目录：conf/（nginx.conf）、html/（静态资源目录）、logs/、temp/、nginx.exe</span></span>
<span class="line"><span>  · 先查 80 端口有没有被占：netstat -ano | findStr 80（被占了就准备改端口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【3】部署（PPT 第 26 页）</span></span>
<span class="line"><span>  · 把 dist 里面的文件（不是 dist 文件夹本身）复制到 nginx 的 html 目录</span></span>
<span class="line"><span>  · 如果 80 被占：改 conf/nginx.conf 里 server 块的 listen 80; → listen 90;</span></span>
<span class="line"><span>  · 确认成功：html 目录下直接能看到 index.html 和 assets</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【4】启动 / 重载（PPT 第 26、28 页）</span></span>
<span class="line"><span>  · 在 nginx 安装目录执行：nginx.exe（启动）</span></span>
<span class="line"><span>  · 改过 conf/nginx.conf 的话：nginx.exe -s reload</span></span>
<span class="line"><span>  · 确认在跑：浏览器能打开；或任务管理器里能看到 nginx 进程</span></span>
<span class="line"><span>    （Windows 版双击启动后没有窗口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【5】访问（PPT 第 27 页）</span></span>
<span class="line"><span>  · http://localhost        （80 端口可省略）</span></span>
<span class="line"><span>  · 改过端口就带上：http://localhost:90</span></span>
<span class="line"><span>  · 确认成功：页面显示出来（左侧四个菜单、右上角&quot;修改密码 | 退出登录【…】&quot;）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【6】补充一层：页面里的 /api 请求怎么到后端</span></span>
<span class="line"><span>  · 开发时是 vite.config.js 的代理干的；上线后没有 Vite 了</span></span>
<span class="line"><span>  · 在 conf/nginx.conf 的 server 块里加反向代理（参照 59 篇）：</span></span>
<span class="line"><span>      location ^~ /api/ {</span></span>
<span class="line"><span>          rewrite ^/api/(.*)$ /$1 break;</span></span>
<span class="line"><span>          proxy_pass http://localhost:8080;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>  · 加完 nginx.exe -s reload，再刷新页面验证数据能取到</span></span>
<span class="line"><span>  · proxy_pass 的端口必须和后端实际端口一致</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【7】对照 PPT 第 28 页小结</span></span>
<span class="line"><span>  打包：run build → dist</span></span>
<span class="line"><span>  部署：dist 下的文件 → nginx/html</span></span>
<span class="line"><span>  命令：nginx.exe / nginx.exe -s reload / nginx.exe -s stop</span></span></code></pre></div><p>检查点：① 清单每一步都写了&quot;在哪儿做、怎么确认&quot;；② 第 4 步能说清&quot;改了配置必须重载&quot;；③ 第 6 步能解释&quot;没有这一步页面能开但数据为空（404）&quot;，并写对那三行配置；④ 全程没有把&quot;打包&quot;和&quot;部署&quot;混为一谈（一个在本机工程里、一个在 nginx 目录里）；⑤ 与 PPT 第 28 页那三条命令对得上。</p></details></li></ul>`,78)])])}const u=n(a,[["render",d]]);export{h as __pageData,u as default};
